<script setup lang="ts">
// Headers：KV 表格 + 继承提示（祖先定义、自身未覆盖的 key 灰显列出）
// + 底部灰色只读区：Go 侧运行时自动生成的请求头预览（参照 Postman auto-generated headers）
import { computed } from 'vue'
import KvEditor from '../common/KvEditor.vue'
import { inheritedHeaderKeys } from '../../lib/send'
import { autoGeneratedHeaders } from '../../lib/headers-preview'
import { settings, setSettings } from '../../stores/settings'
import type { Request } from '../../types/models'
import { t } from '../../locales/zh-CN'

const props = defineProps<{ request: Request }>()
const L = computed(() => t())

const inherited = computed(() => [...inheritedHeaderKeys(props.request)])
const autoHeaders = computed(() => autoGeneratedHeaders(props.request))
</script>

<template>
  <div class="ht">
    <KvEditor v-model="request.headers" :description="true" />
    <div v-if="inherited.length > 0" class="ht-inherited">
      <span class="ht-inherited-label">{{ L.request.kv.inherited }}:</span>
      <code v-for="k in inherited" :key="k" class="ht-inherited-key">{{ k }}</code>
    </div>

    <div v-if="autoHeaders.length > 0" class="ht-auto">
      <div v-if="!settings.hideAutoHeaders" class="ht-auto-rows">
        <div v-for="h in autoHeaders" :key="h.key" class="ht-auto-row">
          <span class="ht-auto-key">{{ h.key }}:</span>
          <span class="ht-auto-val">{{ h.value }}</span>
        </div>
      </div>
      <label class="ht-auto-toggle">
        <input type="checkbox" :checked="settings.hideAutoHeaders" @change="setSettings({ hideAutoHeaders: !settings.hideAutoHeaders })" />
        {{ L.request.headers.hide }}
      </label>
    </div>
  </div>
</template>

